goal.statement:
let lam := 2 * Λ / ((↑n - 2) * (↑n - 1));
let mu := fun r => 1 - 2 * M / r ^ (n - 3) - lam * r ^ 2;
M ^ 2 * lam ^ (n - 3) < (↑n - 3) ^ (n - 3) / (↑n - 1) ^ (n - 1) →
  ∃ r_minus r_plus,
    0 < r_minus ∧
      r_minus < r_plus ∧ mu r_minus = 0 ∧ mu r_plus = 0 ∧ ∀ (r : ℝ), 0 < r → mu r = 0 → r = r_minus ∨ r = r_plus

